import path from 'node:path';
import type { BuildContext } from '@teambit/builder';
import type { Component } from '@teambit/component';
import type { EnvContext, EnvHandler } from '@teambit/envs';
import type { Capsule } from '@teambit/isolator';
import type {
  ComponentLintResult,
  Linter,
  LinterContext,
  LintResult,
  LintResults,
} from '@teambit/linter';
import type { Logger } from '@teambit/logger';
import {
  OxlintNode,
  resolveBin,
  resolveTsgolintBin,
  type OxlintJsonDiagnostic,
  type OxlintJsonResult,
} from '@teambit/oxc.linter.oxlint-node';
import { computeOxlintNodeOptions } from './compute-options.js';
import type { OxlintOptions } from './oxlint-linter-options.js';

const emptyJsonResult = (): OxlintJsonResult => ({
  diagnostics: [],
  number_of_files: 0,
  number_of_rules: 0,
  threads_count: 0,
  start_time: 0,
});

type MutableFileResult = Omit<LintResult, 'filePath'> & {
  raw: OxlintJsonDiagnostic[];
};

type LintMessage = LintResult['messages'][number];

export function oxlintDiagnosticToLintMessage(
  diagnostic: OxlintJsonDiagnostic
): LintMessage {
  const span = diagnostic.labels[0]?.span;
  return {
    severity: diagnostic.severity,
    line: span?.line || 1,
    column: span?.column || 1,
    message: `${diagnostic.code}: ${diagnostic.message}`,
    suggestions: diagnostic.help ? [diagnostic.help] : undefined,
  };
}

export class OxlintLinter implements Linter {
  private oxlintNode: OxlintNode;

  constructor(
    readonly id: string = 'oxlint-linter',
    private logger: Logger,
    private options: OxlintOptions
  ) {
    this.oxlintNode = OxlintNode.create(options.oxlintNodeOptions);
  }

  displayName = 'Oxlint';

  displayConfig(): string {
    return JSON.stringify(this.options, null, 2);
  }

  version(): string {
    return this.oxlintNode.version();
  }

  async lint(
    context: LinterContext,
    buildContext?: BuildContext
  ): Promise<LintResults> {
    const longProcessLogger = this.logger.createLongProcessLogger(
      'linting components',
      context.components.length
    );
    this.oxlintNode = OxlintNode.create(
      computeOxlintNodeOptions(this.options.oxlintNodeOptions, context)
    );

    const fileToComponent = new Map<string, Component>();
    const allFiles: string[] = [];
    context.componentsDirMap.components.forEach((component) => {
      longProcessLogger.logProgress(
        `component: ${component.id.toString()}, # of files: ${component.filesystem.files.length}`
      );
      this.getFilesPaths(component, buildContext).forEach((filePath) => {
        allFiles.push(filePath);
        fileToComponent.set(this.normalizePath(filePath), component);
      });
    });

    let jsonResult = emptyJsonResult();
    if (allFiles.length > 0) {
      try {
        const lintResults = await this.oxlintNode.run(allFiles);
        if (!lintResults.json) {
          throw new Error('Oxlint did not return the requested JSON result');
        }
        jsonResult = lintResults.json;
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        this.logger.error(message);
        throw error;
      }
    }

    const diagnosticsByComponent = new Map<string, OxlintJsonDiagnostic[]>();
    const unmappedFiles = new Set<string>();
    jsonResult.diagnostics.forEach((diagnostic) => {
      const component = fileToComponent.get(
        this.normalizePath(diagnostic.filename)
      );
      if (!component) {
        unmappedFiles.add(diagnostic.filename);
        return;
      }

      const componentId = component.id.toString();
      const diagnostics = diagnosticsByComponent.get(componentId) || [];
      diagnostics.push(diagnostic);
      diagnosticsByComponent.set(componentId, diagnostics);
    });

    const errors: Error[] = [];
    if (unmappedFiles.size > 0) {
      const error = new Error(
        `Oxlint reported diagnostics for files that could not be matched to a component: ${Array.from(
          unmappedFiles
        ).join(', ')}`
      );
      this.logger.error(error.message);
      errors.push(error);
    }

    const results = context.componentsDirMap.components.map((component) => {
      const diagnostics =
        diagnosticsByComponent.get(component.id.toString()) || [];
      return this.computeComponentResult(component, diagnostics);
    });
    const totals = this.computeManyComponentsTotals(results);

    return {
      ...totals,
      results,
      isClean: totals.isClean && errors.length === 0,
      errors,
    };
  }

  private normalizePath(filePath: string): string {
    const normalized = path.normalize(path.resolve(process.cwd(), filePath));
    return process.platform === 'win32' ? normalized.toLowerCase() : normalized;
  }

  private getFilesPaths(
    component: Component,
    buildContext?: BuildContext
  ): string[] {
    let capsule: Capsule | undefined;
    if (buildContext) {
      capsule = buildContext.capsuleNetwork.graphCapsules.getCapsule(component.id);
    }

    return component.filesystem.files
      .filter(
        (file) =>
          !this.options.extensions ||
          this.options.extensions.includes(file.extname)
      )
      .map((file) =>
        capsule ? path.join(capsule.path, file.relative) : file.path
      );
  }

  private computeComponentResult(
    component: Component,
    diagnostics: OxlintJsonDiagnostic[]
  ): ComponentLintResult {
    const files: Record<string, MutableFileResult> = {};
    let totalErrorCount = 0;
    let totalWarningCount = 0;

    diagnostics.forEach((diagnostic) => {
      const isError = diagnostic.severity === 'error';
      totalErrorCount += isError ? 1 : 0;
      totalWarningCount += isError ? 0 : 1;

      files[diagnostic.filename] ||= {
        errorCount: 0,
        warningCount: 0,
        messages: [],
        raw: [],
      };
      const file = files[diagnostic.filename];
      file.errorCount += isError ? 1 : 0;
      file.warningCount += isError ? 0 : 1;
      file.messages.push(oxlintDiagnosticToLintMessage(diagnostic));
      file.raw.push(diagnostic);
    });

    const results = Object.entries(files).map(([filePath, result]) => ({
      filePath,
      ...result,
    }));
    const output = this.formatOutput(totalErrorCount, totalWarningCount);

    return {
      component,
      output,
      totalErrorCount,
      totalFatalErrorCount: 0,
      totalFixableErrorCount: 0,
      totalFixableWarningCount: 0,
      totalWarningCount,
      results,
      isClean: totalErrorCount === 0 && totalWarningCount === 0,
    };
  }

  private formatOutput(errorCount: number, warningCount: number): string {
    const summary = `Found ${warningCount} warning(s) and ${errorCount} error(s).`;
    if (errorCount === 0 && warningCount === 0) return summary;
    return `${summary}\nSome issues may be auto-fixable. Run bit lint with the --fix flag to apply safe fixes.`;
  }

  private computeManyComponentsTotals(
    componentsResults: ComponentLintResult[]
  ): Omit<LintResults, 'results' | 'errors'> {
    let totalErrorCount = 0;
    let totalFatalErrorCount = 0;
    let totalFixableErrorCount = 0;
    let totalFixableWarningCount = 0;
    let totalWarningCount = 0;
    let totalComponentsWithErrorCount = 0;
    let totalComponentsWithFatalErrorCount = 0;
    let totalComponentsWithFixableErrorCount = 0;
    let totalComponentsWithFixableWarningCount = 0;
    let totalComponentsWithWarningCount = 0;
    let isClean = true;

    componentsResults.forEach((result) => {
      if (result.totalErrorCount) {
        totalErrorCount += result.totalErrorCount;
        totalComponentsWithErrorCount += 1;
        isClean = false;
      }
      if (result.totalFatalErrorCount) {
        totalFatalErrorCount += result.totalFatalErrorCount;
        totalComponentsWithFatalErrorCount += 1;
        isClean = false;
      }
      if (result.totalFixableErrorCount) {
        totalFixableErrorCount += result.totalFixableErrorCount;
        totalComponentsWithFixableErrorCount += 1;
      }
      if (result.totalFixableWarningCount) {
        totalFixableWarningCount += result.totalFixableWarningCount;
        totalComponentsWithFixableWarningCount += 1;
      }
      if (result.totalWarningCount) {
        totalWarningCount += result.totalWarningCount;
        totalComponentsWithWarningCount += 1;
        isClean = false;
      }
    });

    return {
      totalErrorCount,
      totalFatalErrorCount,
      totalFixableErrorCount,
      totalFixableWarningCount,
      totalWarningCount,
      totalComponentsWithErrorCount,
      totalComponentsWithFatalErrorCount,
      totalComponentsWithFixableErrorCount,
      totalComponentsWithFixableWarningCount,
      totalComponentsWithWarningCount,
      isClean,
    };
  }

  private static resolveBinPath(
    binName: string,
    executable: string,
    specificPath: string | undefined,
    fallbackDirs: string[]
  ): string | undefined {
    if (specificPath) return specificPath;
    for (const fallbackDir of fallbackDirs) {
      try {
        return resolveBin(binName, {
          executable,
          paths: [fallbackDir],
        });
      } catch {
        // Try the next dependency root.
      }
    }
    return undefined;
  }

  private static resolveTsgolintBinPath(
    specificPath: string | undefined,
    fallbackDirs: string[]
  ): string | undefined {
    if (specificPath) return specificPath;
    for (const fallbackDir of fallbackDirs) {
      try {
        return resolveTsgolintBin([fallbackDir]);
      } catch {
        // Try the next dependency root.
      }
    }
    return OxlintLinter.resolveBinPath(
      'oxlint-tsgolint',
      'tsgolint',
      undefined,
      fallbackDirs
    );
  }

  static create(
    options: OxlintOptions,
    { logger }: { logger: Logger }
  ): OxlintLinter {
    const name = options.name || 'oxlint-linter';
    const fallbackDirs = options.binDir ? [options.binDir] : [];
    const binPath = OxlintLinter.resolveBinPath(
      'oxlint',
      'oxlint',
      options.binPath || options.oxlintNodeOptions.binPath,
      fallbackDirs
    );
    const needsTsgolint = Boolean(
      options.tsgolintBinPath ||
        options.oxlintNodeOptions.tsgolintBinPath ||
        options.oxlintNodeOptions.typeAware ||
        options.oxlintNodeOptions.typeCheck
    );
    const tsgolintBinPath = needsTsgolint
      ? OxlintLinter.resolveTsgolintBinPath(
          options.tsgolintBinPath || options.oxlintNodeOptions.tsgolintBinPath,
          fallbackDirs
        )
      : undefined;

    return new OxlintLinter(name, logger, {
      ...options,
      oxlintNodeOptions: {
        ...options.oxlintNodeOptions,
        binPath,
        tsgolintBinPath,
      },
    });
  }

  static from(options: OxlintOptions): EnvHandler<OxlintLinter> {
    return (context: EnvContext) => {
      const logger = context.createLogger(options.name || 'oxlint-linter');
      return OxlintLinter.create(options, { logger });
    };
  }
}
